// ─── PART 5 — INCOMPLETE SENTENCES (30 questions) ───
export var BOSS_P5 = [
  // === Easy (1-10) ===
  {id:"bp5_1",s:"The new employee handbook will be _____ to all staff by the end of the week.",o:["distribute","distributed","distributing","distribution"],c:1,x:"Future passive: 'will be distributed'. Past participle after 'will be'.",cat:"Passive Voice"},
  {id:"bp5_2",s:"Sales figures have improved _____ since the new strategy was implemented.",o:["significance","significant","significantly","signify"],c:2,x:"Adverb 'significantly' modifies the verb 'have improved'. How did they improve? Significantly.",cat:"Word Families"},
  {id:"bp5_3",s:"Please confirm your attendance _____ the deadline of April 15.",o:["until","by","on","since"],c:1,x:"'By' expresses a deadline: no later than April 15. 'Until' means continuously up to a point.",cat:"Prepositions"},
  {id:"bp5_4",s:"Ms. Chen _____ the marketing team for over eight years before her promotion.",o:["leads","led","has led","was leading"],c:1,x:"'For over eight years before her promotion' = completed past duration. Past simple 'led'.",cat:"Tenses"},
  {id:"bp5_5",s:"The workshop is designed _____ participants with practical negotiation skills.",o:["provide","to provide","providing","provided"],c:1,x:"'Designed to provide' — infinitive of purpose. What is the design for? To provide skills.",cat:"Gerunds vs Infinitives"},
  {id:"bp5_6",s:"_____ you have any questions about the policy, please contact Human Resources.",o:["Should","Would","Could","Might"],c:0,x:"'Should you have' = formal conditional inversion, meaning 'If you have'. Common in business English.",cat:"Conditionals"},
  {id:"bp5_7",s:"The company's annual report highlights its _____ to environmental sustainability.",o:["commit","committed","commitment","committing"],c:2,x:"'Its' + _____ + 'to' = noun needed. 'Commitment to' = standard collocation.",cat:"Word Families"},
  {id:"bp5_8",s:"Employees who wish to work remotely must _____ written approval from their manager.",o:["obtain","obtaining","obtained","to obtain"],c:0,x:"'Must' + base verb (bare infinitive). 'Must obtain'. No 'to' after modal verbs.",cat:"Gerunds vs Infinitives"},
  {id:"bp5_9",s:"The building was renovated last year, and it now looks _____ modern.",o:["complete","completely","completion","completed"],c:1,x:"Adverb 'completely' modifies the adjective 'modern'. Completely modern.",cat:"Word Families"},
  {id:"bp5_10",s:"The train to the airport _____ every thirty minutes during peak hours.",o:["depart","departs","departing","departed"],c:1,x:"Present simple for timetables and schedules. Third person singular: 'departs'.",cat:"Tenses"},

  // === Medium (11-20) ===
  {id:"bp5_11",s:"The consultant _____ report was presented last week has been hired on a permanent basis.",o:["who","whose","whom","which"],c:1,x:"'Whose report' = possessive relative pronoun. The consultant's report.",cat:"Relative Pronouns"},
  {id:"bp5_12",s:"Although the initial cost is high, the long-term savings make the investment _____.",o:["worth","worthy","worthwhile","worthless"],c:2,x:"'Make something worthwhile' = make it valuable enough to justify the cost. 'Worthwhile' = adjective meaning 'worth the time/money'.",cat:"Vocabulary"},
  {id:"bp5_13",s:"All passengers are advised to keep their personal belongings with them _____ all times.",o:["in","at","on","for"],c:1,x:"'At all times' = always. Fixed prepositional phrase.",cat:"Prepositions"},
  {id:"bp5_14",s:"The factory will remain closed _____ the safety inspection has been completed.",o:["while","during","until","by"],c:2,x:"'Until' = up to the point when. The factory stays closed until the inspection is done.",cat:"Connectors"},
  {id:"bp5_15",s:"Mr. Nakamura suggested _____ the product launch to coincide with the trade fair.",o:["to schedule","scheduling","schedule","to scheduling"],c:1,x:"'Suggest' takes gerund (-ing). 'Suggested scheduling'. Never 'suggest to do'.",cat:"Gerunds vs Infinitives"},
  {id:"bp5_16",s:"The software update is expected to _____ improve system performance across all departments.",o:["drama","dramatic","dramatically","dramatize"],c:2,x:"Adverb 'dramatically' modifies the verb 'improve'. Expected to dramatically improve.",cat:"Word Families"},
  {id:"bp5_17",s:"Both the CEO and the CFO _____ present at the shareholders' meeting.",o:["was","is","were","has been"],c:2,x:"'Both... and' = plural subject. 'Both the CEO and the CFO WERE present.'",cat:"Subject-Verb Agreement"},
  {id:"bp5_18",s:"The seminar will take place in the auditorium _____ can seat up to 300 people.",o:["where","which","whose","whom"],c:1,x:"'Which' refers to the auditorium (a thing). 'The auditorium which can seat 300.' 'Where' would need a different structure.",cat:"Relative Pronouns"},
  {id:"bp5_19",s:"Applicants are required to provide two professional references _____ submitting their application.",o:["while","when","upon","despite"],c:2,x:"'Upon submitting' = at the moment of submitting. Formal for 'when they submit'.",cat:"Connectors"},
  {id:"bp5_20",s:"The new branch office has been _____ located near the central train station.",o:["strategy","strategic","strategically","strategize"],c:2,x:"Adverb 'strategically' modifies the past participle 'located'. How is it located? Strategically.",cat:"Word Families"},

  // === Hard (21-30) ===
  {id:"bp5_21",s:"Were the contract to be terminated early, the supplier _____ entitled to compensation.",o:["is","will be","would be","has been"],c:2,x:"Subjunctive conditional: 'Were the contract to be terminated' = 'If the contract were terminated'. Result: 'would be'.",cat:"Conditionals"},
  {id:"bp5_22",s:"The number of customer complaints _____ decreased steadily over the past quarter.",o:["have","has","are","were"],c:1,x:"'The number of' = singular subject → 'has decreased'. Contrast: 'A number of complaints HAVE...'",cat:"Subject-Verb Agreement"},
  {id:"bp5_23",s:"Not until the audit is complete _____ the merger proceed.",o:["will","does","can","shall"],c:0,x:"Negative adverbial inversion: 'Not until X will Y happen.' Subject-auxiliary inversion after 'Not until'.",cat:"Connectors"},
  {id:"bp5_24",s:"The director insisted that every department _____ a detailed progress report.",o:["submits","submit","submitted","submitting"],c:1,x:"Subjunctive after 'insisted that': base form verb, no -s. 'That every department submit.'",cat:"Tenses"},
  {id:"bp5_25",s:"Ms. Okafor, _____ appointment as regional director was announced yesterday, will start on June 1.",o:["who","whose","whom","which"],c:1,x:"'Whose appointment' = possessive. Ms. Okafor's appointment.",cat:"Relative Pronouns"},
  {id:"bp5_26",s:"The proposed merger is subject to regulatory _____ from both countries.",o:["approve","approval","approved","approvingly"],c:1,x:"'Regulatory approval' — noun after adjective. 'Subject to approval' = standard collocation.",cat:"Word Families"},
  {id:"bp5_27",s:"Hardly had the keynote speaker finished _____ the audience began asking questions.",o:["than","when","that","before"],c:1,x:"'Hardly had... when...' = fixed correlative structure. As soon as she finished, questions started.",cat:"Connectors"},
  {id:"bp5_28",s:"The terms of the agreement are _____ to those of the previous contract.",o:["compare","comparable","comparatively","comparison"],c:1,x:"'Comparable to' = adjective + preposition. Similar in nature to the previous contract.",cat:"Word Families"},
  {id:"bp5_29",s:"Each of the candidates _____ required to complete a skills assessment before the interview.",o:["are","is","were","have been"],c:1,x:"'Each of' = always singular. 'Each of the candidates IS required.' The subject is 'each', not 'candidates'.",cat:"Subject-Verb Agreement"},
  {id:"bp5_30",s:"The company attributed its record profits to the _____ execution of its global strategy.",o:["success","successful","successfully","succeed"],c:1,x:"Adjective before noun: 'successful execution'. The noun 'execution' needs an adjective modifier.",cat:"Word Families"},
];

